import itertools

def get_price(sequence):
    max_p = 0
    current_sum = 0
    for x in sequence:
        current_sum += x
        max_p = max(max_p, abs(current_sum))
    return max_p

def get_sam_price(numbers):
    min_s = float('inf')
    for p in itertools.permutations(numbers):
        min_s = min(min_s, get_price(p))
    return min_s

def get_george_prices(numbers):
    min_abs = min(abs(x) for x in numbers)
    indices = list(range(len(numbers)))
    min_abs_indices = [i for i in indices if abs(numbers[i]) == min_abs]

    results = []
    for start_idx in min_abs_indices:
        current_sequence = [numbers[start_idx]]
        remaining_indices = [i for i in indices if i != start_idx]
        current_sum = numbers[start_idx]

        def explore_george(curr_seq, curr_sum, rem_indices):
            if not rem_indices:
                results.append(get_price(curr_seq))
                return

            best_val = float('inf')
            best_indices = []
            for i in rem_indices:
                val = abs(curr_sum + numbers[i])
                if val < best_val:
                    best_val = val
                    best_indices = [i]
                elif val == best_val:
                    best_indices.append(i)

            for i in best_indices:
                new_seq = curr_seq + [numbers[i]]
                explore_george(new_seq, curr_sum + numbers[i], [idx for idx in rem_indices if idx != i])

        explore_george(current_sequence, current_sum, remaining_indices)
    return results

min_ratio = 1.0
# Try all sets of size 3 from {-5, ..., 5}
for combo in itertools.combinations(range(-5, 6), 3):
    numbers = list(combo)
    s = get_sam_price(numbers)
    gs = get_george_prices(numbers)
    for g in gs:
        min_ratio = min(min_ratio, s / g)

print(f"Min ratio for m=3, elements in [-5, 5]: {min_ratio}")

