import itertools
import random

def get_price(seq):
    prefix_sums = []
    current_sum = 0
    for x in seq:
        current_sum += x
        prefix_sums.append(abs(current_sum))
    return max(prefix_sums)

def get_s(nums):
    min_price = float('inf')
    for p in itertools.permutations(nums):
        price = get_price(p)
        if price < min_price:
            min_price = price
    return min_price

def get_g(nums):
    def get_all_george_sequences(current_nums, current_prefix_sum):
        if not current_nums:
            return [[]]
        min_abs = float('inf')
        for x in current_nums:
            min_abs = min(min_abs, abs(current_prefix_sum + x))
        best_next_elements = [x for x in current_nums if abs(current_prefix_sum + x) == min_abs]
        all_sequences = []
        for x in best_next_elements:
            temp_nums = list(current_nums)
            temp_nums.remove(x)
            sub_sequences = get_all_george_sequences(temp_nums, current_prefix_sum + x)
            for sub in sub_sequences:
                all_sequences.append([x] + sub)
        return all_sequences

    min_abs_a1 = float('inf')
    for x in nums:
        min_abs_a1 = min(min_abs_a1, abs(x))
    best_a1_elements = [x for x in nums if abs(x) == min_abs_a1]
    all_george_sequences = []
    for a1 in best_a1_elements:
        temp_nums = list(nums)
        temp_nums.remove(a1)
        sub_sequences = get_all_george_sequences(temp_nums, a1)
        for sub in sub_sequences:
            all_george_sequences.append([a1] + sub)
    return [get_price(seq) for seq in all_george_sequences]

def find_min_ratio_m(m):
    min_ratio = 1.0
    for _ in range(5000):
        nums = [random.uniform(-100, 100) for _ in range(m)]
        s = get_s(nums)
        gs = get_g(nums)
        for g in gs:
            min_ratio = min(min_ratio, s / g)
    return min_ratio

for m in range(2, 10):
    res = find_min_ratio_m(m)
    print(f"m={m}, min_ratio={res}")

