def get_george_prices(nums):
    def get_george_sequences(current_nums, current_prefix_sum):
        if not current_nums:
            return [([], 0)]
        if current_prefix_sum == 0:
            min_abs = min(abs(x) for x in current_nums)
            candidates = [x for x in current_nums if abs(x) == min_abs]
        else:
            min_val = min(abs(current_prefix_sum + x) for x in current_nums)
            candidates = [x for x in current_nums if abs(current_prefix_sum + x) == min_val]
        results = []
        for c in candidates:
            remaining = list(current_nums)
            remaining.remove(c)
            sub_results = get_george_sequences(remaining, current_prefix_sum + c)
            for sub_seq, sub_price in sub_results:
                results.append(([c] + sub_seq, max(abs(current_prefix_sum + c), sub_price)))
        return results

    sequences = get_george_sequences(nums, 0)
    return [res[1] for res in sequences]

